118	func tryPushSessionsCommon(ctx context.Context, remote, branchName string) error {
119		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
120		defer cancel()
121	
122		// Use --no-verify to prevent recursive hook calls
123		cmd := CheckpointGitCommand(ctx, remote, "push", "--no-verify", remote, branchName)
124	
125		output, err := cmd.CombinedOutput()
126		if err != nil {
127			// Check if it's a non-fast-forward error (we can try to recover)
128			if strings.Contains(string(output), "non-fast-forward") ||
129				strings.Contains(string(output), "rejected") {
130				return errors.New("non-fast-forward")
131			}
132			return fmt.Errorf("push failed: %s", output)
133		}
134		return nil
135	}
